def transfer(db, src, dst, amount):
    with db.transaction(isolation="SERIALIZABLE"):
        bal = db.query_one("SELECT balance FROM accounts WHERE id = %s", src)
        if bal < amount:
            raise InsufficientFunds()
        db.execute("UPDATE accounts SET balance = balance - %s WHERE id = %s", amount, src)
        db.execute("UPDATE accounts SET balance = balance + %s WHERE id = %s", amount, dst)

@app.post("/transfer")
def handle(req):
    transfer(db, req.src, req.dst, req.amount)  # any database error becomes HTTP 500
    return ok()
